const form = useAppForm({
  defaultValues: { email: '' },
  validators: { onChange: z.object({ email: z.email() }) },
  onSubmit: async ({ value }) => { await saveEmail(value); },
});
<Form form={form}>
  <form.AppField name="email">
    {(field) => <field.EmailField label="Email" required />}
  </form.AppField>
  <form.SubmitButton />
</Form>

